from flask import Blueprint, request, jsonify
from app.services.constitution import calculate_constitution
from app.utils.security import token_required

assessment_bp = Blueprint('assessment', __name__)

@assessment_bp.route('/submit', methods=['POST'])
@token_required
def submit_assessment():
    data = request.get_json()
    if not data or 'answers' not in data:
        return jsonify({'error': '缺少 answers 字段'}), 400
    result = calculate_constitution(data['answers'])
    return jsonify(result), 200

import uuid
import logging
from flask import request, jsonify, g

logger = logging.getLogger(__name__)

def register_middleware(app):
    @app.before_request
    def before_request():
        # 生成或透传请求 ID
        request_id = request.headers.get('X-Request-ID', str(uuid.uuid4()))
        g.request_id = request_id
        logger.info(f"[{request_id}] {request.method} {request.path}")

    @app.after_request
    def after_request(response):
        response.headers['X-Request-ID'] = getattr(g, 'request_id', '')
        return response

    @app.errorhandler(Exception)
    def handle_exception(e):
        request_id = getattr(g, 'request_id', '')
        logger.error(f"[{request_id}] Unhandled exception: {e}", exc_info=True)
        return jsonify({
            'error': '服务器内部错误',
            'request_id': request_id
        }), 500

import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { login as apiLogin } from '@/api'

export const useUserStore = defineStore('user', () => {
  // state
  const token = ref(localStorage.getItem('token') || '')
  const userInfo = ref(null)

  // getters
  const isLoggedIn = computed(() => !!token.value)

  // actions
  const login = async (username, password) => {
    const res = await apiLogin(username, password)
    token.value = res.data.token
    userInfo.value = res.data.user
    localStorage.setItem('token', res.data.token)
    return res.data
  }

  const logout = () => {
    token.value = ''
    userInfo.value = null
    localStorage.removeItem('token')
  }

  return { token, userInfo, isLoggedIn, login, logout }
})

