from sentence_transformers import SentenceTransformer

class EmbeddingModel:
    def __init__(self, model_name='BAAI/bge-small-zh-v1.5'):
        self.model = SentenceTransformer(model_name)

    def encode(self, texts):
        """将文本列表转换为向量"""
        return self.model.encode(texts, normalize_embeddings=True)

    def encode_query(self, query):
        """编码查询（bge 模型查询前需加指令）"""
        instruction = "为这个句子生成表示以用于检索相关文章："
        return self.model.encode([instruction + query], normalize_embeddings=True)[0]

import numpy as np import faiss
class FAISSVectorStore: def __init__(self, dimension=512): self.dimension = dimension # 使用内积索引（向量已归一化时等价于余弦相似度） self.index = faiss.IndexFlatIP(dimension) self.documents = []
def add_documents(self, documents, embeddings): """添加文档和对应向量""" vectors = np.array(embeddings, dtype='float32') self.index.add(vectors) self.documents.extend(documents)
def search(self, query_vector, top_k=3): """检索最相似的 top_k 个文档""" query = np.array([query_vector], dtype='float32') scores, indices = self.index.search(query, top_k) results = [] for score, idx in zip(scores[0], indices[0]): if idx >= 0: results.append({ 'document': self.documents[idx], 'score': float(score) }) return results
def save(self, path): """持久化到磁盘""" faiss.write_index(self.index, f"{path}/index.faiss") import json with open(f"{path}/documents.json", 'w', encoding='utf-8') as f: json.dump(self.documents, f, ensure_ascii=False)
def load(self, path): """从磁盘加载""" self.index = faiss.read_index(f"{path}/index.faiss") import json with open(f"{path}/documents.json", 'r', encoding='utf-8') as f: self.documents = json.load(f)

class CaseRetriever:
    def __init__(self, embedding_model, vector_store):
        self.embedding_model = embedding_model
        self.vector_store = vector_store

    def retrieve(self, query, top_k=3):
        """根据用户症状描述检索相似案例"""
        query_vector = self.embedding_model.encode_query(query)
        return self.vector_store.search(query_vector, top_k=top_k)

    def build_context(self, query, top_k=3):
        """构建 RAG 上下文，供 LLM 使用"""
        cases = self.retrieve(query, top_k=top_k)
        context_parts = []
        for i, case in enumerate(cases, 1):
            context_parts.append(
                f"参考案例 {i}（相似度 {case['score']:.2f}）：\n"
                f"症状：{case['document']['symptoms']}\n"
                f"体质：{case['document']['constitution']}\n"
                f"方案：{case['document']['plan']}"
            )
        return "\n\n".join(context_parts)

import json
from langchain_ollama import OllamaLLM
from app.config import Config

class BaseAgent:
    def __init__(self, name, system_prompt, tools=None):
        self.name = name
        self.system_prompt = system_prompt
        self.tools = tools or {}
        self.llm = OllamaLLM(
            model=Config.OLLAMA_MODEL,
            base_url=Config.OLLAMA_BASE_URL,
            temperature=0.3
        )

    def _build_messages(self, user_input, context=None):
        messages = [{"role": "system", "content": self.system_prompt}]
        if context:
            messages.append({"role": "system", "content": f"参考信息：\n{context}"})
        messages.append({"role": "user", "content": user_input})
        return messages

    def _parse_json_response(self, response):
        """从模型输出中提取 JSON"""
        try:
            # 尝试直接解析
            return json.loads(response)
        except json.JSONDecodeError:
            # 尝试提取 ```json ... ``` 块
            import re
            match = re.search(r'```json\s*(.*?)\s*```', response, re.DOTALL)
            if match:
                return json.loads(match.group(1))
            raise

    def run(self, user_input, context=None):
        messages = self._build_messages(user_input, context)
        response = self.llm.invoke(
            "\n".join(m["content"] for m in messages)
        )
        return self._parse_json_response(response)

SYMPTOM_PROMPT = """你是中医症状分析专家。请从用户描述中提取结构化信息，以 JSON 格式输出：
{
  "symptoms": ["症状1", "症状2"],
  "tongue": {"color": "舌色", "coating": "舌苔"},
  "pulse": "脉象描述",
  "severity": "轻度/中度/重度",
  "duration": "持续时间"
}
只输出 JSON，不要其他文字。"""

class SymptomAgent(BaseAgent):
    def __init__(self):
        super().__init__("symptom", SYMPTOM_PROMPT)

    def analyze(self, user_input):
        return self.run(user_input)

from app.services.confidence import check_confidence from app.services.grounding import validate_entities
class MasterAgent: def __init__(self, symptom_agent, constitution_agent, plan_agent, session_store): self.symptom_agent = symptom_agent self.constitution_agent = constitution_agent self.plan_agent = plan_agent self.session_store = session_store
def chat(self, session_id, user_input): # 1. 症状分析 symptom_data = self.symptom_agent.analyze(user_input)
# 2. 体质推理 constitution_result = self.constitution_agent.infer(symptom_data)
# 3. 置信度门控 if not check_confidence(constitution_result['confidence']): return { "stage": "clarification", "message": "您的症状描述还不够明确，能否补充以下信息：舌象、脉象、症状持续时间？", "confidence": constitution_result['confidence'] }
# 4. 方案生成 plan = self.plan_agent.generate(constitution_result['constitution'])
# 5. 幻觉抑制：实体锚定校验 plan = validate_entities(plan)
# 6. 保存会话状态 self.session_store.save(session_id, { "symptoms": symptom_data, "constitution": constitution_result, "plan": plan })
return { "stage": "plan", "constitution": constitution_result['constitution'], "confidence": constitution_result['confidence'], "plan": plan }

import time
import logging
from app.config import Config

logger = logging.getLogger(__name__)

class ToolRegistry:
    def __init__(self):
        self._tools = {}

    def register(self, name, func, description, parameters):
        """注册工具"""
        self._tools[name] = {
            'func': func,
            'description': description,
            'parameters': parameters
        }

    def get_tool_definitions(self):
        """获取所有工具的 OpenAI 格式定义（供 Function Calling 使用）"""
        return [
            {
                'type': 'function',
                'function': {
                    'name': name,
                    'description': tool['description'],
                    'parameters': tool['parameters']
                }
            }
            for name, tool in self._tools.items()
        ]

    def call(self, name, **kwargs):
        """调用工具，含超时和重试"""
        if name not in self._tools:
            raise ValueError(f"工具 {name} 未注册")

        tool = self._tools[name]
        last_error = None

        for attempt in range(Config.TOOL_MAX_RETRIES):
            try:
                start = time.time()
                result = tool['func'](**kwargs)
                elapsed = time.time() - start
                logger.info(f"工具 {name} 调用成功，耗时 {elapsed:.2f}s")
                return result
            except Exception as e:
                last_error = e
                logger.warning(f"工具 {name} 第 {attempt+1} 次调用失败: {e}")
                if attempt < Config.TOOL_MAX_RETRIES - 1:
                    time.sleep(1 * (attempt + 1))

        raise last_error

# 注册示例
registry = ToolRegistry()

def query_foods(constitution):
    from py2neo import Graph
    graph = Graph(Config.NEO4J_URI, auth=(Config.NEO4J_USER, Config.NEO4J_PASSWORD))
    result = graph.run("""
        MATCH (c:Constitution {name: $name})-[:RECOMMENDS]->(f:Food)
        RETURN f.name AS name, f.effect AS effect
    """, name=constitution)
    return [dict(r) for r in result]

registry.register(
    name='query_foods',
    func=query_foods,
    description='查询指定体质推荐的食材',
    parameters={
        'type': 'object',
        'properties': {
            'constitution': {'type': 'string', 'description': '体质名称，如气虚质'}
        },
        'required': ['constitution']
    }
)

-- 用户表 CREATE TABLE users ( id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(256) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- 问卷题目表 CREATE TABLE questions ( id INT AUTO_INCREMENT PRIMARY KEY, content TEXT NOT NULL, dimension VARCHAR(50) NOT NULL, -- 对应体质维度 reverse_score BOOLEAN DEFAULT FALSE, sort_order INT DEFAULT 0 ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- 测评结果表 CREATE TABLE assessment_results ( id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, scores JSON NOT NULL, -- 九种体质得分 primary_constitution VARCHAR(50), secondary_constitution VARCHAR(50), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

// 创建体质节点
CREATE (:Constitution {name: '气虚质', description: '元气不足，疲乏、气短、自汗'});
CREATE (:Constitution {name: '阳虚质', description: '阳气不足，畏寒怕冷、手足不温'});
CREATE (:Constitution {name: '阴虚质', description: '阴液亏少，口燥咽干、手足心热'});

// 创建食材节点
CREATE (:Food {name: '山药', effect: '健脾益胃、滋肾益精', nature: '平', taste: '甘'});
CREATE (:Food {name: '红枣', effect: '补中益气、养血安神', nature: '温', taste: '甘'});

// 创建穴位节点
CREATE (:Acupoint {name: '足三里', location: '犊鼻下3寸，胫骨前嵴外一横指', method: '每次按压5-10分钟，每日2次'});

// 创建关系：体质推荐食材
MATCH (c:Constitution {name: '气虚质'}), (f:Food {name: '山药'})
CREATE (c)-[:RECOMMENDS {reason: '健脾益气'}]->(f);

// 创建关系：穴位治疗体质
MATCH (a:Acupoint {name: '足三里'}), (c:Constitution {name: '气虚质'})
CREATE (a)-[:TREATS]->(c);

// 创建索引（提升查询性能）
CREATE INDEX FOR (c:Constitution) ON (c.name);
CREATE INDEX FOR (f:Food) ON (f.name);
CREATE INDEX FOR (a:Acupoint) ON (a.name);

import redis
import json
from app.config import Config

class SessionStore:
    def __init__(self):
        if Config.REDIS_URL:
            self.client = redis.from_url(Config.REDIS_URL, decode_responses=True)
            self.use_redis = True
        else:
            # 内存 fallback
            self._store = {}
            self.use_redis = False

    def save(self, session_id, data, ttl=None):
        ttl = ttl or Config.SESSION_TTL
        payload = json.dumps(data, ensure_ascii=False)
        if self.use_redis:
            self.client.setex(f"session:{session_id}", ttl, payload)
        else:
            self._store[session_id] = payload

    def get(self, session_id):
        if self.use_redis:
            data = self.client.get(f"session:{session_id}")
        else:
            data = self._store.get(session_id)
        return json.loads(data) if data else None

    def delete(self, session_id):
        if self.use_redis:
            self.client.delete(f"session:{session_id}")
        else:
            self._store.pop(session_id, None)

server {
    listen 80;
    server_name localhost;
    root /usr/share/nginx/html;
    index index.html;

    # 前端路由 fallback 到 index.html（SPA 支持）
    location / {
        try_files $uri $uri/ /index.html;
    }

    # API 反向代理到后端容器
    location /api/ {
        proxy_pass http://backend:5000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_read_timeout 120s;
    }

    # 静态资源缓存
    location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg)$ {
        expires 30d;
        add_header Cache-Control "public, immutable";
    }
}
